#!/bin/sh
# Compiles ChangedLines.java for Java 8 against Pitest's plugin API and writes
# its bytes into src/pitest-filter.ts, which embeds them in the binary. Run it
# after editing the filter:
#   sh packs/jvm/src/assets/pitest/build.sh <pitest.jar> <pitest-entry.jar>
set -eu
here=$(cd "$(dirname "$0")" && pwd)
out=$(mktemp -d)
javac --release 8 -nowarn -cp "$1:$2" -d "$out" "$here/gauntlet/ChangedLines.java"
bytes=$(base64 < "$out/gauntlet/ChangedLines.class" | tr -d '\n')
cat > "$here/../../pitest-filter.ts" <<TS
// Generated by src/assets/pitest/build.sh from src/assets/pitest/gauntlet/ChangedLines.java: don't edit.

/** The compiled Pitest filter that keeps only the mutants on a change's lines (spec 0019). */
export const FILTER_CLASS = "gauntlet.ChangedLines"

/** The Pitest feature it provides. */
export const FILTER_FEATURE = "gauntletlines"

/** Its class file (Java 8), base64. */
export const FILTER_BYTES = "$bytes"
TS
rm -rf "$out"
